    async def guardar_pagina(self, *, wiki: Union[str, int], slug: Union[str, int], body: GuardarPaginaBody, request_options: Optional[RequestOptions] = None) -> Outcome[GuardarPaginaResult]:
        """Create or edit a wiki page

        Saves `content` as a NEW revision of the page (creating it if it does not exist; the slug is normalised). History only grows. A save identical to the current revision changes nothing and answers `unchanged: true`. Editorial team (admin/editor), or an agent with wiki:update / wiki:create; a `locked` page only an admin (403).

        REST: `PUT /api/wiki/wikis/{wiki}/pages/{slug}` · scope `kon:wiki:guardar-pagina`
        idempotent (safe to retry) · MCP tool `wiki__guardar-pagina`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            wiki: Wiki slug (e.g. elden-ring)
            slug: Page slug inside that wiki
        """
        return await self._call(OPERATIONS["guardar-pagina"], {"wiki": wiki, "slug": slug}, body, request_options)

