    async def revertir_pagina(self, *, wiki: Union[str, int], slug: Union[str, int], number: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[RevertirPaginaResult]:
        """Revert a page to an earlier revision

        Brings back the content of revision `number` as a NEW revision (nothing is deleted: the history keeps proving what happened). 404 if the page or the revision does not exist, 409 if it is already the current one. Same permission as editing the page.

        REST: `POST /api/wiki/wikis/{wiki}/pages/{slug}/revert/{number}` · scope `kon:wiki:revertir-pagina`
        not idempotent (an Idempotency-Key is sent automatically) · sensitive: may come back as a proposal pending human approval · MCP tool `wiki__revertir-pagina`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            wiki: Wiki slug (e.g. elden-ring)
            slug: Page slug inside that wiki
            number: Revision number to bring back
        """
        return await self._call(OPERATIONS["revertir-pagina"], {"wiki": wiki, "slug": slug, "number": number}, None, request_options)

